// Defines the UTC reporting window. Single source of truth for every project.
// For a backfill, temporarily raise LOOKBACK_DAYS (e.g. 7) and run manually.
const LOOKBACK_DAYS = 1;

const now = new Date();
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const start = new Date(end.getTime() - LOOKBACK_DAYS * 86400000);
const iso = (d) => d.toISOString().slice(0, 19) + 'Z';

return [{
  json: {
    window_start: iso(start),
    window_end: iso(end),
    report_date: iso(start).slice(0, 10),
    lookback_days: LOOKBACK_DAYS,
    run_at: iso(now)
  }
}];

// Flattens every page of the Zendesk search export into one item per ticket,
// de-duplicates, and re-filters on exact UTC bounds (Zendesk search date
// handling can be timezone-sensitive, so we never trust it alone).
const cfg = $('P1 · Config').first().json;
const start = new Date(cfg.window_start).getTime();
const end = new Date(cfg.window_end).getTime();

const out = [];
const seen = new Set();
let sawResults = false;
let sawError = false;

for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error || body.__error) sawError = true;
  if (Object.prototype.hasOwnProperty.call(body, 'results')) sawResults = true;
  const results = body.results || [];
  for (const t of results) {
    if (!t || !t.id) continue;
    const created = new Date(t.created_at).getTime();
    if (!(created >= start && created < end)) continue;
    if (seen.has(t.id)) continue;
    seen.add(t.id);
    out.push({ json: t });
  }
}

// Never return zero items: an empty branch would be skipped by n8n and the
// project would silently vanish from the report.
// Distinguish "quiet day" from "Zendesk call failed" - reporting fake zeros
// for a failed fetch would be worse than saying nothing.
if (!out.length) return [{ json: { __no_tickets: true, fetch_failed: (sawError || !sawResults) } }];
return out;

// Chunks ticket IDs into batches of 100 for /tickets/show_many.
// ids=0 is a deliberate no-op: Zendesk returns 200 with an empty array,
// which keeps the branch alive on a zero-ticket day.
const tickets = $('P1 · Flatten Tickets').all().map(i => i.json).filter(t => t && t.id);
const ids = tickets.map(t => t.id);
const SIZE = 100;

if (!ids.length) return [{ json: { chunk: 0, ids: '0', empty: true } }];

const out = [];
for (let i = 0; i < ids.length; i += SIZE) {
  out.push({ json: { chunk: i / SIZE, ids: ids.slice(i, i + SIZE).join(','), empty: false } });
}
return out;

// ===========================================================================
//  Joins tickets + metric sets + users, then computes every number in the
//  report. All counting happens here, in code. The LLM never counts anything.
// ===========================================================================
const cfg  = $('P1 · Config').first().json;
const TEXT_LIMIT       = 240;   // chars of opening message sent to Gemini
const MAX_PER_BUCKET   = 2000;  // hard payload guard

// ---- 1. Merge sources ------------------------------------------------------
const base = {};
for (const it of $('P1 · Flatten Tickets').all()) {
  const t = it.json;
  if (t && t.id) base[t.id] = t;
}

const metricById = {};
const userById   = {};
for (const it of $('P1 · Fetch Metrics + Users').all()) {
  const b = (it && it.json) || {};
  for (const t of (b.tickets || []))     if (t && t.id && base[t.id]) base[t.id] = Object.assign({}, base[t.id], t);
  for (const m of (b.metric_sets || [])) if (m && m.ticket_id) metricById[m.ticket_id] = m;
  for (const u of (b.users || []))       if (u && u.id) userById[u.id] = u;
}

const tickets = Object.values(base).filter(t => t && t.id);
const fetchFailed = $('P1 · Flatten Tickets').all().some(i => i && i.json && i.json.fetch_failed === true);

// ---- 2. Category taxonomy --------------------------------------------------
// Slug normalisation absorbs per-instance quirks (double vs triple
// underscores, slashes, trailing punctuation) so one map serves all projects.
const norm = (s) => String(s == null ? '' : s)
  .toLowerCase().trim()
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/_+/g, '_')
  .replace(/^_|_$/g, '');

const BUCKETS = [
  { key: 'refunds',       emoji: '\ud83d\udcb0', label: 'Refunds' },
  { key: 'cancellations', emoji: '\ud83d\udeab', label: 'Cancellations' },
  { key: 'billing',       emoji: '\ud83d\udcb3', label: 'Billing & Payments' },
  { key: 'chargeback',    emoji: '\u2696\ufe0f', label: 'Chargebacks & Fraud' },
  { key: 'unidentified',  emoji: '\ud83d\udce7', label: 'Unidentified Contact' },
  { key: 'technical',     emoji: '\ud83d\udee0', label: 'Technical Issues' },
  { key: 'product',       emoji: '\ud83e\udded', label: 'Product & Pricing' },
  { key: 'feedback',      emoji: '\u2b50', label: 'Feedback & Reviews' },
  { key: 'other',         emoji: '\u2753', label: 'Other' }
];

const CATEGORY_MAP = {
  refund_within_30_days_monthly:            'refunds',
  refund_30_day_policy_last_charge_only:     'refunds',
  refund_30_day_policy_two_last_charges:     'refunds',
  refund_within_30_days_trial:               'refunds',
  refund_upsell:                             'refunds',
  refund_paypal2025:                         'refunds',
  refund_rejection:                          'refunds',
  refund_rejection_complaint:                'refunds',
  cancellation_subscription:                 'cancellations',
  cancellation_account_removal:              'cancellations',
  billing:                                   'billing',
  bug_billing:                               'billing',
  disputed_user:                             'chargeback',
  fraudulent_user:                           'chargeback',
  password_and_account_info:                 'unidentified',
  bug_technical_issue:                       'technical',
  service_down:                              'technical',
  results_not_received:                      'technical',
  product_info:                              'product',
  pricing:                                   'product',
  subscription:                              'product',
  feature_request:                            'feedback',
  trustpilot_review:                         'feedback',
  other:                                     'other',
  different_platform_website:                'other',
  special_offers_discounts:                  'other',
  spam:                                      '__noise',
  duplicate_contact:                         '__noise'
};

// Per-project overrides, e.g. {"weird_slug":"refunds"}
let overrides = {};
try { overrides = cfg.category_override_map ? JSON.parse(cfg.category_override_map) : {}; } catch (e) { overrides = {}; }

const bucketFor = (slug) => {
  const n = norm(slug);
  if (!n) return '__uncategorised';
  if (overrides[n]) return overrides[n];
  if (CATEGORY_MAP[n]) return CATEGORY_MAP[n];
  // Prefix fallbacks so brand-new options land somewhere sane.
  if (n.startsWith('refund')) return 'refunds';
  if (n.startsWith('cancellation')) return 'cancellations';
  if (n.startsWith('bug')) return 'technical';
  return '__unmapped';
};

const categoryOf = (t) => {
  const fid = Number(cfg.category_field_id);
  const f = (t.custom_fields || []).find(x => Number(x.id) === fid);
  return f && f.value != null && f.value !== '' ? String(f.value) : '';
};

// ---- 3. Automation classification -----------------------------------------
const johnId  = Number(cfg.automation_agent_id) || 0;
const autoTag = String(cfg.automation_tag || '').trim();
const automationEnabled = johnId > 0;

const isSolved   = (t) => t.status === 'solved' || t.status === 'closed';
const johnSolved = (t) => automationEnabled && Number(t.assignee_id) === johnId;
const johnTouched = (t) => (autoTag && Array.isArray(t.tags) && t.tags.includes(autoTag)) || johnSolved(t);

const classOf = (t) => {
  if (!automationEnabled) return 'manual';
  if (johnSolved(t)) return 'auto';
  if (autoTag && Array.isArray(t.tags) && t.tags.includes(autoTag)) return 'assisted';
  return 'manual';
};

// ---- 4. Stats helpers ------------------------------------------------------
const cal = (v) => (v && typeof v === 'object' && v.calendar != null) ? Number(v.calendar) : null;
const avg = (a) => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
const med = (a) => {
  if (!a.length) return null;
  const s = a.slice().sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

// ---- 5. Volume -------------------------------------------------------------
const received = tickets.length;
const solved   = tickets.filter(isSolved);
const wasReopened = (t) => {
  const m = metricById[t.id];
  return !!(m && Number(m.reopens) > 0);
};
const reopenedTickets = tickets.filter(wasReopened);
const reopened = reopenedTickets.length;
const refunds = tickets.filter(t => norm(categoryOf(t)).startsWith('refund')).length;

// ---- 6. Automation split ---------------------------------------------------
const solvedByClass = { auto: [], assisted: [], manual: [] };
for (const t of solved) solvedByClass[classOf(t)].push(t);
const touched = tickets.filter(johnTouched).length;

// A ticket that was solved and then reopened is currently 'open', so it is NOT
// in `solved`. Reopen rate therefore needs its own denominator: everything that
// reached solved at least once.
const everSolvedByClass = { auto: [], assisted: [], manual: [] };
for (const t of tickets) {
  if (isSolved(t) || wasReopened(t)) everSolvedByClass[classOf(t)].push(t);
}
const reopenSplit = { auto: 0, assisted: 0, manual: 0 };
for (const t of reopenedTickets) reopenSplit[classOf(t)]++;

// ---- 7. Performance (solved tickets only, three columns) -------------------
const perf = {};
for (const k of ['auto', 'assisted', 'manual']) {
  const set = solvedByClass[k];
  const frt = [], res = [], rep = [];
  let oneTouch = 0, repCount = 0;
  for (const t of set) {
    const m = metricById[t.id] || {};
    const a = cal(m.reply_time_in_minutes);
    const b = cal(m.full_resolution_time_in_minutes);
    if (a != null) frt.push(a);
    if (b != null) res.push(b);
    if (m.replies != null) { rep.push(Number(m.replies)); repCount++; if (Number(m.replies) === 1) oneTouch++; }
  }
  const ever = everSolvedByClass[k];
  const reo = ever.filter(wasReopened).length;
  perf[k] = {
    n: set.length,
    ever_solved: ever.length,
    reopened: reo,
    reopen_pct: ever.length ? (reo / ever.length) * 100 : null,
    frt_avg: avg(frt), frt_med: med(frt),
    res_avg: avg(res), res_med: med(res),
    rep_avg: avg(rep),
    one_touch_pct: repCount ? (oneTouch / repCount) * 100 : null
  };
}

// ---- 8. Solved by agent ----------------------------------------------------
const agentCounts = {};
for (const t of solved) {
  let name;
  if (t.assignee_id == null) name = 'Unassigned';
  else if (automationEnabled && Number(t.assignee_id) === johnId) name = cfg.automation_agent_name || 'Automation';
  else name = (userById[t.assignee_id] && userById[t.assignee_id].name) || ('User ' + t.assignee_id);
  agentCounts[name] = (agentCounts[name] || 0) + 1;
}
const autoName = cfg.automation_agent_name || 'Automation';
const agents = Object.keys(agentCounts)
  .map(name => ({ name, count: agentCounts[name] }))
  .sort((a, b) => {
    if (a.name === autoName) return -1;
    if (b.name === autoName) return 1;
    if (a.name === 'Unassigned') return 1;
    if (b.name === 'Unassigned') return -1;
    return b.count - a.count;
  });

// ---- 9. Request breakdown --------------------------------------------------
const grouped = {};
BUCKETS.forEach(b => { grouped[b.key] = []; });
const noiseDetail = {};
const unmappedDetail = {};
let noiseTotal = 0, uncategorised = 0, unmappedTotal = 0;

for (const t of tickets) {
  const raw = categoryOf(t);
  const b = bucketFor(raw);
  if (b === '__noise') {
    noiseTotal++;
    const n = norm(raw);
    noiseDetail[n] = (noiseDetail[n] || 0) + 1;
  } else if (b === '__uncategorised') {
    uncategorised++;
  } else if (b === '__unmapped') {
    unmappedTotal++;
    unmappedDetail[raw] = (unmappedDetail[raw] || 0) + 1;
  } else {
    grouped[b].push(t);
  }
}

const denom = BUCKETS.reduce((s, b) => s + grouped[b.key].length, 0);
const uniqueCustomers = new Set(
  BUCKETS.flatMap(b => grouped[b.key]).map(t => t.requester_id).filter(x => x != null)
).size;

// Per-type refund breakdown. Labels are derived from the slug rather than
// hardcoded, so a new refund option appears automatically on every project.
const refundSet = grouped.refunds;
const refundCounts = {};
for (const t of refundSet) {
  const n = norm(categoryOf(t)) || 'unspecified';
  refundCounts[n] = (refundCounts[n] || 0) + 1;
}
const refundTypes = Object.keys(refundCounts).map(slug => ({
  slug,
  label: slug.replace(/^refund_/, '').replace(/_/g, ' ').trim() || 'unspecified',
  count: refundCounts[slug]
})).sort((a, b) => b.count - a.count);

const breakdown = BUCKETS.map(b => ({
  key: b.key,
  emoji: b.emoji,
  label: b.label,
  count: grouped[b.key].length,
  pct: denom ? (grouped[b.key].length / denom) * 100 : 0
}));

// ---- 10. Text payloads for Gemini -----------------------------------------
// Ticket id + subject + truncated opening message only.
// No customer names, no email addresses, no full threads leave the stack.
const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, TEXT_LIMIT);
const brief = (t) => ({ id: String(t.id), subject: clean(t.subject), text: clean(t.description) });

const themeInputs = {};
for (const b of BUCKETS) {
  if (!grouped[b.key].length) continue;
  themeInputs[b.key] = grouped[b.key].slice(0, MAX_PER_BUCKET).map(brief);
}

return [{
  json: {
    project_key: cfg.project_key,
    project_display_name: cfg.project_display_name,
    gemini_model: cfg.gemini_model,
    report_date: cfg.report_date,
    window_start: cfg.window_start,
    window_end: cfg.window_end,
    fetch_failed: fetchFailed,
    automation_enabled: automationEnabled,
    automation_agent_name: autoName,
    automation_tag: autoTag,
    volume: {
      received,
      solved: solved.length,
      still_open: received - solved.length,
      reopened,
      reopen_split: reopenSplit,
      refunds,
      resolution_rate: received ? (solved.length / received) * 100 : 0
    },
    automation: {
      auto: solvedByClass.auto.length,
      assisted: solvedByClass.assisted.length,
      manual: solvedByClass.manual.length,
      touch_rate: received ? (touched / received) * 100 : 0
    },
    performance: perf,
    agents,
    breakdown: {
      denom,
      unique_customers: uniqueCustomers,
      noise_total: noiseTotal,
      noise_detail: noiseDetail,
      uncategorised,
      unmapped_total: unmappedTotal,
      unmapped_detail: unmappedDetail,
      buckets: breakdown,
      refund_types: refundTypes
    },
    theme_inputs: themeInputs,
    tech_tickets: (grouped.technical || []).slice(0, MAX_PER_BUCKET).map(brief)
  }
}];

// One Gemini call per (project, bucket). Every ticket in the bucket is sent -
// no sampling - so the theme reflects the full day.
const projects = $('All Projects').all().map(i => i.json);

const NOOP_BODY = {
  contents: [{ role: 'user', parts: [{ text: 'Return the JSON object {"ok":true}.' }] }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 64,
    responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { ok: { type: 'BOOLEAN' } }, required: ['ok'] }
  }
};

const SYSTEM = [
  'You analyse customer support tickets.',
  'You receive the subject and the opening message of every ticket filed in one category group on a single day.',
  'Write exactly one sentence of at most 25 words describing what these customers were actually contacting support about.',
  'Name the dominant concrete driver rather than restating the category name.',
  'If there are two clear drivers, mention both and roughly how they split.',
  'Do not invent anything that is not present in the tickets. Do not mention counts or percentages.',
  'Return JSON only, in the form {"theme":"..."}.'
].join(' ');

const SCHEMA = {
  type: 'OBJECT',
  properties: { theme: { type: 'STRING' } },
  required: ['theme']
};

const out = [];

for (const p of projects) {
  const model = p.gemini_model;
  for (const b of (p.breakdown.buckets || [])) {
    const tix = (p.theme_inputs || {})[b.key] || [];
    if (!tix.length) continue;
    const lines = tix.map(t => '- ' + (t.subject || '(no subject)') + ' :: ' + (t.text || '')).join('\n');
    out.push({
      json: {
        project_key: p.project_key,
        bucket_key: b.key,
        job: 'theme',
        model,
        request_body: {
          systemInstruction: { parts: [{ text: SYSTEM }] },
          contents: [{ role: 'user', parts: [{ text: 'Category group: ' + b.label + '\nTickets (' + tix.length + '):\n' + lines }] }],
          generationConfig: {
            temperature: 0.2,
            // Gemini 3.x spends reasoning tokens out of maxOutputTokens, so the
            // budget is generous and thinking is kept low for a one-line answer.
            thinkingConfig: { thinkingLevel: 'low' },
            maxOutputTokens: 2048,
            responseMimeType: 'application/json',
            responseSchema: SCHEMA
          }
        }
      }
    });
  }
}

// Keep the chain alive when nothing at all came in today.
if (!out.length) {
  out.push({
    json: {
      project_key: (projects[0] && projects[0].project_key) || 'none',
      bucket_key: null,
      job: 'noop',
      model: (projects[0] && projects[0].gemini_model) || 'gemini-3.6-flash',
      request_body: NOOP_BODY
    }
  });
}

return out;

// Re-attaches theme text to each project. Response items align 1:1 with the
// job items because the HTTP node always emits one output per input.
const projects = $('All Projects').all().map(i => i.json);
const jobs = $('Explode Theme Jobs').all().map(i => i.json);
const resp = $input.all();

const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};

const themes = {};
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i];
  if (!job || job.job !== 'theme') continue;
  const parsed = resp[i] ? readJson(resp[i]) : null;
  const theme = parsed && parsed.theme ? String(parsed.theme).trim() : '';
  themes[job.project_key] = themes[job.project_key] || {};
  themes[job.project_key][job.bucket_key] = theme;
}

return projects.map(p => ({ json: Object.assign({}, p, { themes: themes[p.project_key] || {} }) }));

// Pass 1 of 2: discover the day's recurring technical issue types.
// Labels only - no counting, no per-ticket assignment yet.
const NOOP_BODY = {
  contents: [{ role: 'user', parts: [{ text: 'Return the JSON object {"ok":true}.' }] }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 64,
    responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { ok: { type: 'BOOLEAN' } }, required: ['ok'] }
  }
};

const SYSTEM = [
  'You cluster technical customer support tickets into recurring issue types.',
  'You receive the subject and opening message of every technical ticket from a single day.',
  'Return between 3 and 8 short labels, each 2 to 5 words, naming a distinct concrete technical problem.',
  'Labels must be mutually exclusive and together cover the majority of the tickets.',
  'Do not include a catch-all label such as Other or Miscellaneous; a separate Other bucket is added automatically.',
  'Return JSON only, in the form {"labels":["...","..."]}.'
].join(' ');

const SCHEMA = {
  type: 'OBJECT',
  properties: { labels: { type: 'ARRAY', items: { type: 'STRING' } } },
  required: ['labels']
};

return $input.all().map(item => {
  const p = item.json;
  const tix = p.tech_tickets || [];
  if (!tix.length) {
    return { json: Object.assign({}, p, { job: 'noop', model: p.gemini_model, request_body: NOOP_BODY }) };
  }
  const lines = tix.map(t => '- ' + (t.subject || '(no subject)') + ' :: ' + (t.text || '')).join('\n');
  return {
    json: Object.assign({}, p, {
      job: 'discover',
      model: p.gemini_model,
      request_body: {
        systemInstruction: { parts: [{ text: SYSTEM }] },
        contents: [{ role: 'user', parts: [{ text: 'Technical tickets (' + tix.length + '):\n' + lines }] }],
        generationConfig: {
          temperature: 0.2,
          thinkingConfig: { thinkingLevel: 'low' },
          maxOutputTokens: 2048,
          responseMimeType: 'application/json',
          responseSchema: SCHEMA
        }
      }
    })
  };
});

// Pass 2 of 2: assign each technical ticket to one of the discovered labels.
// Chunked at 80 tickets per call to keep every response short and complete.
const projects = $('Prepare Tech Discovery').all().map(i => i.json);
const resp = $input.all();
const CHUNK = 80;

const NOOP_BODY = {
  contents: [{ role: 'user', parts: [{ text: 'Return the JSON object {"ok":true}.' }] }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 64,
    responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { ok: { type: 'BOOLEAN' } }, required: ['ok'] }
  }
};

const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};

const SYSTEM = [
  'You assign technical support tickets to issue types.',
  'You receive a fixed list of labels and a list of tickets, each with an id.',
  'Assign every ticket to exactly one label from the list.',
  'If a ticket genuinely fits none of the labels, use the exact string Other.',
  'Return one entry per input ticket, reusing the ids exactly as given.',
  'Return JSON only, in the form {"assignments":[{"id":"123","label":"..."}]}.'
].join(' ');

const SCHEMA = {
  type: 'OBJECT',
  properties: {
    assignments: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: { id: { type: 'STRING' }, label: { type: 'STRING' } },
        required: ['id', 'label']
      }
    }
  },
  required: ['assignments']
};

const out = [];

for (let i = 0; i < projects.length; i++) {
  const p = projects[i];
  const parsed = resp[i] ? readJson(resp[i]) : null;
  let labels = (parsed && Array.isArray(parsed.labels) ? parsed.labels : [])
    .map(x => String(x || '').trim()).filter(Boolean).slice(0, 8);
  const tix = p.tech_tickets || [];

  if (!tix.length || !labels.length) {
    out.push({ json: { project_key: p.project_key, job: 'noop', labels, model: p.gemini_model, request_body: NOOP_BODY } });
    continue;
  }

  for (let j = 0; j < tix.length; j += CHUNK) {
    const slice = tix.slice(j, j + CHUNK);
    const lines = slice.map(t => t.id + ' | ' + (t.subject || '(no subject)') + ' :: ' + (t.text || '')).join('\n');
    out.push({
      json: {
        project_key: p.project_key,
        job: 'classify',
        labels,
        model: p.gemini_model,
        request_body: {
          systemInstruction: { parts: [{ text: SYSTEM }] },
          contents: [{ role: 'user', parts: [{ text: 'Labels:\n' + labels.map(l => '- ' + l).join('\n') + '\n\nTickets:\n' + lines }] }],
          generationConfig: {
            temperature: 0,
            thinkingConfig: { thinkingLevel: 'low' },
            maxOutputTokens: 16384,
            responseMimeType: 'application/json',
            responseSchema: SCHEMA
          }
        }
      }
    });
  }
}

return out;

// Counting happens here, never in the model. Any ticket the model failed to
// classify falls into Other, so the total always reconciles.
const projects = $('Prepare Tech Discovery').all().map(i => i.json);
const jobs = $('Prepare Tech Classify').all().map(i => i.json);
const resp = $input.all();

const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};

const assignedByProject = {};
const labelsByProject = {};

for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i];
  if (!job) continue;
  labelsByProject[job.project_key] = job.labels || [];
  if (job.job !== 'classify') continue;

  const valid = new Set(job.labels || []);
  const parsed = resp[i] ? readJson(resp[i]) : null;
  const arr = (parsed && Array.isArray(parsed.assignments)) ? parsed.assignments : [];

  assignedByProject[job.project_key] = assignedByProject[job.project_key] || {};
  const store = assignedByProject[job.project_key];
  for (const a of arr) {
    const id = String((a && a.id) != null ? a.id : '').trim();
    if (!id || store[id]) continue;
    store[id] = valid.has(a.label) ? a.label : 'Other';
  }
}

return projects.map(p => {
  const tix = p.tech_tickets || [];
  const store = assignedByProject[p.project_key] || {};
  const counts = {};
  for (const t of tix) {
    const lab = store[String(t.id)] || 'Other';
    counts[lab] = (counts[lab] || 0) + 1;
  }
  const items = Object.keys(counts)
    .map(label => ({ label, count: counts[label] }))
    .sort((a, b) => (a.label === 'Other' ? 1 : b.label === 'Other' ? -1 : b.count - a.count));

  return { json: Object.assign({}, p, { tech: { total: tix.length, items, labels: labelsByProject[p.project_key] || [] } }) };
});

// Renders the Slack message. Wrapped in a code block so the monospace font
// preserves column alignment; emoji are kept out of aligned number columns.
const pad  = (s, n) => String(s).padEnd(n);
const padL = (s, n) => String(s).padStart(n);

const dur = (m) => {
  if (m == null || isNaN(m)) return '-';
  const t = Math.round(Number(m));
  if (t < 60) return t + 'm';
  const h = Math.floor(t / 60);
  const mm = t % 60;
  return h + 'h ' + (mm < 10 ? '0' : '') + mm + 'm';
};
const pct = (v) => (v == null || isNaN(v)) ? '-' : (Math.round(Number(v) * 10) / 10).toFixed(1) + '%';
const one = (v) => (v == null || isNaN(v)) ? '-' : (Math.round(Number(v) * 10) / 10).toFixed(1);
const rule = (t) => '\u2501\u2501\u2501 ' + t + ' ' + '\u2501'.repeat(Math.max(3, 46 - t.length));

// Word-wrap for the code block: Slack will not break a long line for us.
const wrap = (text, width, indent) => {
  const words = String(text || '').split(/\s+/).filter(Boolean);
  const lines = [];
  let cur = '';
  for (const w of words) {
    if (!cur.length) cur = w;
    else if ((cur + ' ' + w).length <= width) cur += ' ' + w;
    else { lines.push(indent + cur); cur = w; }
  }
  if (cur.length) lines.push(indent + cur);
  return lines;
};

return $input.all().map(item => {
  const p = item.json;
  const v = p.volume, a = p.automation, f = p.performance, bd = p.breakdown;
  const L = [];

  if (p.fetch_failed) {
    L.push('\u26a0\ufe0f *CS Report \u00b7 ' + p.project_display_name + ' \u00b7 ' + p.report_date + '*');
    L.push('Could not retrieve tickets from Zendesk for this window, so no report was produced.');
    L.push('The other projects are unaffected. Check the failed execution in n8n.');
    return { json: Object.assign({}, p, { slack_text: L.join('\n') }) };
  }

  L.push('\ud83d\udcca *CS Report \u00b7 ' + p.project_display_name + ' \u00b7 ' + p.report_date + '*');
  L.push('```');
  L.push('Cohort: tickets received ' + p.report_date + ' 00:00-23:59 UTC');
  L.push('');

  L.push(rule('VOLUME'));
  L.push(pad('Received', 26) + padL(v.received, 6));
  L.push(pad('Solved', 26) + padL(v.solved, 6) + '   (' + pct(v.resolution_rate) + ' of received)');
  L.push(pad('Still open', 26) + padL(v.still_open, 6));
  if (p.automation_enabled && v.reopened) {
    const rs = v.reopen_split || {};
    L.push(pad('Reopened', 26) + padL(v.reopened, 6) +
      '   (auto ' + (rs.auto || 0) + ' \u00b7 assisted ' + (rs.assisted || 0) + ' \u00b7 manual ' + (rs.manual || 0) + ')');
  } else {
    L.push(pad('Reopened', 26) + padL(v.reopened, 6));
  }
  L.push(pad('Refund requests', 26) + padL(v.refunds, 6));
  L.push('');

  if (p.automation_enabled) {
    L.push(rule('AUTOMATION'));
    const share = (n) => v.solved ? '   (' + pct((n / v.solved) * 100) + ' of solved)' : '';
    L.push(pad('Fully automated', 26) + padL(a.auto, 6) + share(a.auto));
    L.push(pad('Assisted (bot then human)', 26) + padL(a.assisted, 6) + share(a.assisted));
    L.push(pad('Fully manual', 26) + padL(a.manual, 6) + share(a.manual));
    L.push(pad('Automation touch rate', 26) + padL(pct(a.touch_rate), 6) + '   (of received)');
    if (!p.automation_tag) {
      L.push('! No automation tag configured - assisted tickets count as manual.');
    }
    L.push('');

    L.push(rule('PERFORMANCE (solved)'));
    L.push(pad('', 26) + pad('Auto', 12) + pad('Assisted', 12) + pad('Manual', 12));
    L.push(pad('Solved tickets', 26) + pad(f.auto.n, 12) + pad(f.assisted.n, 12) + pad(f.manual.n, 12));
    L.push(pad('First response   avg', 26) + pad(dur(f.auto.frt_avg), 12) + pad(dur(f.assisted.frt_avg), 12) + pad(dur(f.manual.frt_avg), 12));
    L.push(pad('                 med', 26) + pad(dur(f.auto.frt_med), 12) + pad(dur(f.assisted.frt_med), 12) + pad(dur(f.manual.frt_med), 12));
    L.push(pad('Resolution       avg', 26) + pad(dur(f.auto.res_avg), 12) + pad(dur(f.assisted.res_avg), 12) + pad(dur(f.manual.res_avg), 12));
    L.push(pad('                 med', 26) + pad(dur(f.auto.res_med), 12) + pad(dur(f.assisted.res_med), 12) + pad(dur(f.manual.res_med), 12));
    L.push(pad('Agent replies    avg', 26) + pad(one(f.auto.rep_avg), 12) + pad(one(f.assisted.rep_avg), 12) + pad(one(f.manual.rep_avg), 12));
    L.push(pad('One-touch rate', 26) + pad(pct(f.auto.one_touch_pct), 12) + pad(pct(f.assisted.one_touch_pct), 12) + pad(pct(f.manual.one_touch_pct), 12));
    L.push(pad('Reopen rate', 26) + pad(pct(f.auto.reopen_pct), 12) + pad(pct(f.assisted.reopen_pct), 12) + pad(pct(f.manual.reopen_pct), 12));
  } else {
    L.push(rule('PERFORMANCE (solved)'));
    L.push(pad('First response   avg/med', 26) + dur(f.manual.frt_avg) + ' / ' + dur(f.manual.frt_med));
    L.push(pad('Resolution       avg/med', 26) + dur(f.manual.res_avg) + ' / ' + dur(f.manual.res_med));
    L.push(pad('Agent replies    avg', 26) + one(f.manual.rep_avg));
    L.push(pad('One-touch rate', 26) + pct(f.manual.one_touch_pct));
    L.push(pad('Reopen rate', 26) + pct(f.manual.reopen_pct));
  }
  L.push('');

  L.push(rule('SOLVED BY AGENT'));
  if (!p.agents.length) L.push('  (none)');
  for (const ag of p.agents) L.push(pad('  ' + ag.name, 26) + padL(ag.count, 6));
  L.push('');

  L.push(rule('REQUEST BREAKDOWN'));
  L.push('Categorised: ' + bd.denom + '  \u00b7  Unique customers: ' + bd.unique_customers);
  const nd = Object.keys(bd.noise_detail).map(k => k.replace(/_/g, ' ') + ' ' + bd.noise_detail[k]).join(' \u00b7 ');
  L.push('Noise excluded: ' + bd.noise_total + (nd ? '  (' + nd + ')' : ''));
  L.push('');

  for (const b of bd.buckets) {
    if (!b.count) continue;
    L.push(b.emoji + ' ' + b.label + ' \u2014 ' + b.count + ' (' + pct(b.pct) + ')');
    const th = (p.themes || {})[b.key];
    for (const ln of wrap(th || 'theme unavailable', 68, '     ')) L.push(ln);
    if (b.key === 'refunds') {
      for (const r of (bd.refund_types || [])) {
        L.push(pad('     \u21b3 ' + r.label, 44) + padL(r.count, 5));
      }
    }
    L.push('');
  }

  if (bd.unmapped_total) {
    const u = Object.keys(bd.unmapped_detail).map(k => k + ' (' + bd.unmapped_detail[k] + ')').join(', ');
    L.push('\u26a0\ufe0f Unmapped categories \u2014 ' + bd.unmapped_total);
    for (const ln of wrap(u, 68, '     ')) L.push(ln);
    L.push('');
  }
  if (bd.uncategorised) {
    L.push('\u2754 No category set \u2014 ' + bd.uncategorised);
    L.push('');
  }

  L.push(rule('TECHNICAL ISSUES'));
  L.push('Technical tickets: ' + p.tech.total);
  if (!p.tech.total) {
    L.push('  (none today)');
  } else if (!p.tech.items.length) {
    L.push('  (clustering unavailable)');
  } else {
    for (const t of p.tech.items) L.push(pad('  \u2022 ' + t.label, 44) + padL(t.count, 5));
  }
  L.push('```');

  return { json: Object.assign({}, p, { slack_text: L.join('\n') }) };
});
